% QUESTION 1
clear;
clc;
close all;

%%\ Load the ABP signal
% Add the folder containing the MATLAB functions
addpath('PhysioToolkitCardiacOutput_MatlabCode/2analyze');

% Select the patient's ABP txt file
RawData = load(fullfile('s00020', 's00020-2567-03-30-17-47_ABP.txt'));

% Make ABP is a column vector
Time = RawData(:, 1);
ABP = RawData(:, 2);

% Sampling frequency
Fs = 125;

% Display basic information
fprintf('Time between samples: %.4f seconds\n', mean(diff(Time))); %[output:07ac093b]
fprintf('Number of ABP samples: %d\n', length(ABP)); %[output:044ef9ef]
fprintf('Recording duration: %.2f hours\n', (Time(end) - Time(1))/3600); %[output:32b3fe8d]

%%\ Detect heartbeat onsets
% Use the supplied WABP algorithm
OnsetTimes = wabp(ABP);

fprintf('Number of detected pulse onsets: %d\n', length(OnsetTimes)); %[output:1f1fb1aa]

%%\ Extract ABP waveform features
% Use the ABPFEATURE algorithm
Features = abpfeature(ABP, OnsetTimes);

% Feature columns:
% 1  = Systolic time
% 2  = Systolic pressure
% 3  = Diastolic time
% 4  = Diastolic pressure
% 5  = Pulse pressure
% 6  = Mean arterial pressure
% 7  = Beat period
% 8  = Mean negative derivative
% 9  = End systole (0.3*sqrt(RR))
% 10 = Systolic area (0.3*sqrt(RR))
% 11 = End systole (minimum slope)
% 12 = Systolic area (minimum slope)

%%\ Evaluate signal quality
% Use the JSQI algorithm
[BeatQ, QualityRatio] = jSQI(Features, OnsetTimes, ABP);
fprintf('Fraction of good beats: %.3f\n', QualityRatio); %[output:8135cfcd]

%%\ Select the two analysis periods
StartHours = [10, 11];
NumberOfPulses = 20;

for k = 1:length(StartHours) %[output:group:3de4af78]
    % Find the firt sample
    StartSample = find(Time >= StartHours(k)*3600, 1, 'first');

    % Find the first detected onset
    FirstBeat = find(OnsetTimes >= StartHours(k)*3600, 1, 'first');

    if isempty(FirstBeat) || ...
            FirstBeat + NumberOfPulses > length(OnsetTimes)
        error('Not enough detected pulses at hour %d.', ...
            StartHours(k));
    end

    % Select 20 complete pulses
    BeatIndices = FirstBeat:(FirstBeat + NumberOfPulses - 1);

    % Select 21 onset boundaries for the 20 pulses
    SelectedOnsets = OnsetTimes( ...
        FirstBeat:FirstBeat + NumberOfPulses);

    % Corresponding waveform features
    SelectedFeatures = Features(BeatIndices, :);

    % Corresponding signal quality values
    SelectedQuality = BeatQ(BeatIndices, 1);

    % Extract waveform segment
    SegmentStart = SelectedOnsets(1);
    SegmentEnd = SelectedOnsets(end);

    ABPSegment = ABP(SegmentStart:SegmentEnd);

    % Time in seconds
    SegmentTime = (0:length(ABPSegment)-1)/Fs;

    %%\ Extract feature locations
    % Convert absolute sample positions to positions
    SystolicTimes = SelectedFeatures(:,1) - SegmentStart + 1;
    DiastolicTimes = SelectedFeatures(:,3) - SegmentStart + 1;

    EndSystole1 = SelectedFeatures(:,9) - SegmentStart + 1;
    EndSystole2 = SelectedFeatures(:,11) - SegmentStart + 1;

    OnsetRelative = SelectedOnsets(1:end-1) - SegmentStart + 1;

    % Keep feature indices within the waveform
    ValidSystolic = SystolicTimes >= 1 & SystolicTimes <= length(ABPSegment);

    ValidDiastolic = DiastolicTimes >= 1 & DiastolicTimes <= length(ABPSegment);

    ValidEnd1 = EndSystole1 >= 1 & EndSystole1 <= length(ABPSegment);

    ValidEnd2 = EndSystole2 >= 1 & EndSystole2 <= length(ABPSegment);

    %%\ Plot ABP waveform and features
    figure; %[output:4edd80ca] %[output:406993ae]

    plot(SegmentTime, ABPSegment, 'b-', 'LineWidth', 1.2); %[output:4edd80ca] %[output:406993ae]
    hold on;

    % Mark pulse onsets with *
    plot(SegmentTime(OnsetRelative), ABPSegment(OnsetRelative), ...
        'k*', 'MarkerSize', 7);

    % Mark systolic peaks with ^
    plot(SegmentTime(SystolicTimes(ValidSystolic)), ...
        SelectedFeatures(ValidSystolic,2), ...
        'r^', 'MarkerSize', 7, 'MarkerFaceColor', 'r');

    % Mark diastolic points with v
    plot(SegmentTime(DiastolicTimes(ValidDiastolic)), ...
        SelectedFeatures(ValidDiastolic,4), ...
        'bv', 'MarkerSize', 7, 'MarkerFaceColor', 'b')

    % Mark end of systole using 0.3*sqrt(RR) with X
    plot(SegmentTime(EndSystole1(ValidEnd1)), ...
        ABPSegment(EndSystole1(ValidEnd1)), ...
        'mx', 'MarkerSize', 9, 'LineWidth', 1.5);

    % Mark end of systole using minimum slope with o
    plot(SegmentTime(EndSystole2(ValidEnd2)), ...
        ABPSegment(EndSystole2(ValidEnd2)), ...
        'go', 'MarkerSize', 7, 'LineWidth', 1.5);

    %%\ Label and format plot
    xlabel('Time (seconds)');
    ylabel('Arterial Blood Pressure (mmHg)');

    title(sprintf('Patient s00020: First 20 ABP Pulses Starting at %d Hours', ...
        StartHours(k)));

    legend('ABP waveform', ...
        'Pulse onset (*)', ...
        'Systolic peak (^)', ...
        'Diastolic point (v)', ...
        'End systole: 0.3 sqrt(RR) (X)', ...
        'End systole: minimum slope (o)', ...
        'Location', 'best');

    grid on;
    box on;
    hold off;

    %%\ Save figure
    OutputName = sprintf('Q1_ABP_patient20_%dhours.png', StartHours(k));

    saveas(gcf, OutputName);

    fprintf('\nAnalysis at %d hours:\n', StartHours(k)); %[output:38132d73] %[output:92a6598c]
    fprintf('Number of pulses plotted: %d\n', NumberOfPulses); %[output:281cdee9] %[output:140a8063]
    fprintf('Good pulses: %d\n', sum(~SelectedQuality)); %[output:2bde195b] %[output:4b5e4792]
    fprintf('Bad pulses: %d\n', sum(SelectedQuality)); %[output:3ac5d92d] %[output:0d33d027]

end %[output:group:3de4af78]

% Task 3
% Extract data for patient 20 by 2analyze
% Could be the same as in Task 1
%close all;
%clc;

ABP_timeseries = load('s00020/s00020-2567-03-30-17-47_ABP.txt');
TCO_data = readmatrix('s00020/s00020-2567-03-30-17-47n.txt','NumHeaderLines',2);

fs = 125; % Sampling frequency
ts_12 = 12 * 60 * 60; % 12h in second
t_start_abp = ABP_timeseries(1,1); % Extract initial time value
t_start_TCO = TCO_data(1,1); 
ABP_window_12 = ABP_timeseries(:,1) < (ts_12 + t_start_abp); % 12 hour window in second
TCO_window_12 = TCO_data(:,1) < (ts_12 + t_start_TCO); % 12 hour window in minute

% Extract the data from the first 12h
ABP_timeseries_12h = ABP_timeseries(ABP_window_12,:);
TCO_data_12h = TCO_data(TCO_window_12,:);

% Extract the ABP pressure column
abp_pressure_12 = ABP_timeseries_12h(:,2);

%%\ Use helper functions from 2analyze to extract feature from the first 12h
ABP_onset = wabp(abp_pressure_12);  % Detect ABP onset
ABP_feature = abpfeature(abp_pressure_12,ABP_onset); % Extract the 12 ABP features
quality = jSQI(ABP_feature, ABP_onset, abp_pressure_12); % calculate signal quality index

%%\ Use helper functions from 3estimate to get continuous CO
addpath('PhysioToolkitCardiacOutput_MatlabCode/3estimate');
[CO, t_CO, t_old, feat_filtered] = estimateCO_v3(ABP_onset,ABP_feature,quality,5,2);

%%\ C2 Calibration
TCO = TCO_data_12h(:,16);

% Extract the index and value of the first non-zero TCO
r_1_index = find(TCO > 0,1,'first');  
r_1 = TCO(r_1_index);

% Convert index into minute
t_first_valid = TCO_data_12h(r_1_index,1)/60;

% Find the estimate at the 1 min window of timestamp
window = (t_CO > t_first_valid-1) & (t_CO <= t_first_valid);
x_1 = median(CO(window)); % Take the median of the window

% Calculate the calibrating index 
k = r_1/x_1;
CO_cal = k * CO;

% Extract PP, MAP, HR
PP = feat_filtered(:,5);
MAP = feat_filtered(:,6);
BP = feat_filtered(:,7); % extract beat period first
HR = 60*125./BP; % calculate HR and convert into bpm

%%\ Extract episodic thermodilution CO measurements
TCO_valid = TCO(TCO > 0);
index_valid = find(TCO > 0);  
time_TCO_valid = TCO_data_12h(index_valid,1)/60; % timestamp of TCO measurement in minute
HR_TCO = TCO_data_12h(index_valid,2);
PP_TCO = TCO_data_12h(index_valid,3)-TCO_data_12h(index_valid,4);
MAP_TCO = TCO_data_12h(index_valid,5);

%%\ Plot continuous CO, PP, MAP, and HR across time
figure(1);
subplot(4,1,1); %[output:9d64e447]
plot(t_CO,CO_cal); % continuous cardiac output (curve line) %[output:9d64e447]
hold on; %[output:9d64e447]
stem(time_TCO_valid,TCO_valid,"filled",LineWidth = 1.0) % discrete TCO measurement (stem plots) %[output:9d64e447]
xlabel('time (min)'); %[output:9d64e447]
ylabel('CO'); %[output:9d64e447]

subplot(4,1,2); %[output:9d64e447]
plot(t_CO,PP); %[output:9d64e447]
hold on; %[output:9d64e447]
stem(time_TCO_valid,PP_TCO,"filled", LineWidth = 1.0); %[output:9d64e447]
xlabel('time (min)'); %[output:9d64e447]
ylabel('PP'); %[output:9d64e447]

subplot(4,1,3); %[output:9d64e447]
plot(t_CO,MAP); %[output:9d64e447]
hold on; %[output:9d64e447]
stem(time_TCO_valid,MAP_TCO,"filled",LineWidth = 1.0); %[output:9d64e447]
xlabel('time (min)'); %[output:9d64e447]
ylabel('MAP'); %[output:9d64e447]

subplot(4,1,4); %[output:9d64e447]
plot(t_CO,HR); %[output:9d64e447]
hold on; %[output:9d64e447]
stem(time_TCO_valid,HR_TCO,"filled",LineWidth = 1.0); %[output:9d64e447]
xlabel('time (min)'); %[output:9d64e447]
ylabel('HR'); %[output:9d64e447]

% Resize the image to be taller
fig = gcf;
fig.Position(4) = fig.Position(4) + 120; %[output:9d64e447]

% Add overall legend
Lgnd = legend('continuous estimate curve', 'discrete TCO measurement'); %[output:9d64e447]
Lgnd.Position(1) = 0.7; %[output:9d64e447]
Lgnd.Position(2) = 0.94; %[output:9d64e447]

hold off; %[output:9d64e447]

